#Requires -Version 7.3
# SPDX-License-Identifier: GPL-3.0-or-later
# Run-bound physical-edge admission. No OS input is generated by this reader.
function Initialize-MineComeHudWorldNative {
    if('MineCome.HudWorld.Native' -as [type]){return}
    # Public Windows APIs, also used by the existing stream/file identity guards:
    # https://learn.microsoft.com/windows/win32/api/fileapi/nf-fileapi-getfileinformationbyhandle
    # https://learn.microsoft.com/windows/win32/api/winuser/nf-winuser-getforegroundwindow
    Add-Type -TypeDefinition @'
using System;
using System.ComponentModel;
using System.Runtime.InteropServices;
namespace MineCome.HudWorld {
 public static class Native {
  [StructLayout(LayoutKind.Sequential)] struct Info {
   public uint Attributes, CreationLow, CreationHigh, AccessLow, AccessHigh, WriteLow, WriteHigh;
   public uint Volume, SizeHigh, SizeLow, Links, IndexHigh, IndexLow;
  }
  [DllImport("kernel32.dll", SetLastError=true)] static extern bool GetFileInformationByHandle(IntPtr file,out Info info);
  [DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
  [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr window,out uint pid);
  public static string Identity(IntPtr file) {
   Info info;if(!GetFileInformationByHandle(file,out info))throw new Win32Exception(Marshal.GetLastWin32Error());
   return info.Volume.ToString("x8")+":"+info.IndexHigh.ToString("x8")+info.IndexLow.ToString("x8");
  }
  public static bool Foreground(int expected) {
   IntPtr window=GetForegroundWindow();uint pid=0;
   return window!=IntPtr.Zero && GetWindowThreadProcessId(window,out pid)!=0 && pid==(uint)expected;
  }
 }
}
'@
}
function Get-MineComeHudWorldFileIdentity($Stream){[MineCome.HudWorld.Native]::Identity($Stream.SafeFileHandle.DangerousGetHandle())}
function Test-MineComeHudWorldForeground($Context){[MineCome.HudWorld.Native]::Foreground($Context.GamePid)}
function New-MineComeHudWorldClicks($Context,[string]$Path,[string]$Run) {
    if($Run -cnotmatch '^[0-9a-f]{32}$'){throw 'Invalid world-click run.'}
    Assert-MineComeProbeContext $Context
    Initialize-MineComeHudWorldNative
    $path=Assert-MineComeHudStonePath $Path
    $stream=[IO.FileStream]::new($path,[IO.FileMode]::Open,[IO.FileAccess]::Read,([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete))
    try {
        $offset=$stream.Length;$discard=$false
        if($offset -gt 0){$stream.Position=$offset-1;$discard=$stream.ReadByte() -ne 10}
        [pscustomobject]@{
            Context=$Context;Path=$path;Run=$Run;Identity=(Get-MineComeHudWorldFileIdentity $stream)
            InitialOffset=$offset;Offset=$offset;ReadBytes=0L;Pending=[byte[]]@();DiscardInitialFragment=$discard
            Sequence=0L;Failure=$null;Clicks=[Collections.Generic.List[object]]::new()
        }
    }finally{$stream.Dispose()}
}
function ConvertFrom-MineComeHudWorldClick([string]$Line,[string]$Run,[long]$PreviousSequence) {
    if(-not $Line.Contains('[MineComeWorldInput]')){return $null}
    if($Line.Length -gt 4096 -or $Line -cnotmatch '(?:^|\s)\[MineComeWorldInput\] (\{[^\r\n]*\})$'){throw 'Malformed world-click log record.'}
    $json=$Matches[1];$document=[System.Text.Json.JsonDocument]::Parse($json)
    try {
        $root=$document.RootElement
        if($root.ValueKind -ne [System.Text.Json.JsonValueKind]::Object){throw 'World-click JSON must be an object.'}
        $names=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        foreach($property in $root.EnumerateObject()){
            if($property.Name -cnotin @('schema','run','sequence','utc_ms','action') -or -not $names.Add($property.Name)){throw 'Unknown or repeated world-click field.'}
        }
        if($names.Count -ne 5){throw 'Missing world-click field.'}
        $numbers=@{}
        foreach($name in @('schema','sequence','utc_ms','action')){
            $field=$root.GetProperty($name);$raw=$field.GetRawText()
            if($field.ValueKind -ne [System.Text.Json.JsonValueKind]::Number -or $raw -cnotmatch '^[1-9][0-9]{0,18}$'){throw 'World-click field must be a positive integer.'}
            $numbers[$name]=[long]::Parse($raw,[Globalization.CultureInfo]::InvariantCulture)
        }
        $runField=$root.GetProperty('run')
        if($numbers.schema -ne 1 -or $runField.ValueKind -ne [System.Text.Json.JsonValueKind]::String -or $runField.GetString() -cne $Run){throw 'World-click identity differs.'}
        if($PreviousSequence -lt 0 -or $PreviousSequence -ge 16 -or $numbers.sequence -ne $PreviousSequence+1 -or $numbers.action -notin @(1,2)){throw 'World-click sequence/capacity/action invalid.'}
        [pscustomobject]@{sequence=$numbers.sequence;utc_ms=$numbers.utc_ms;action=[int]$numbers.action}
    }finally{$document.Dispose()}
}
function Read-MineComeHudWorldClickLines($State) {
    $null=Assert-MineComeHudStonePath $State.Path
    $stream=[IO.FileStream]::new($State.Path,[IO.FileMode]::Open,[IO.FileAccess]::Read,([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete))
    try {
        if((Get-MineComeHudWorldFileIdentity $stream) -cne $State.Identity){throw 'World-click log file was replaced.'}
        $length=$stream.Length;$available=$length-$State.Offset
        if($available -lt 0){throw 'World-click log file was truncated.'}
        if($available -gt 64KB -or $State.ReadBytes+$available -gt 2MB){throw 'World-click log byte bound exceeded.'}
        if($available -eq 0){return}
        $stream.Position=$State.Offset;$bytes=[byte[]]::new([int]$available);$read=0
        while($read -lt $bytes.Length){$count=$stream.Read($bytes,$read,$bytes.Length-$read);if($count -eq 0){throw 'World-click log truncated during read.'};$read+=$count}
        $State.Offset+=$read;$State.ReadBytes+=$read
        $combined=[byte[]]::new($State.Pending.Length+$bytes.Length)
        [Array]::Copy($State.Pending,0,$combined,0,$State.Pending.Length);[Array]::Copy($bytes,0,$combined,$State.Pending.Length,$bytes.Length)
        $start=0;$utf8=[Text.UTF8Encoding]::new($false,$true)
        for($index=0;$index -lt $combined.Length;$index++){
            if($combined[$index] -ne 10){continue}
            if($index-$start -gt 4096){throw 'World-click log line bound exceeded.'}
            if($State.DiscardInitialFragment){$State.DiscardInitialFragment=$false}
            else {$utf8.GetString($combined,$start,$index-$start).TrimEnd("`r")}
            $start=$index+1
        }
        if($combined.Length-$start -gt 4096){throw 'World-click partial line bound exceeded.'}
        $State.Pending=[byte[]]::new($combined.Length-$start);[Array]::Copy($combined,$start,$State.Pending,0,$State.Pending.Length)
    }finally{$stream.Dispose()}
}
function Get-MineComeHudWorldDecline($State,$Session,$Click,[long]$Now) {
    if($Click.utc_ms -lt $Now-250){return 'stale_edge'}
    if($Click.utc_ms -gt $Now+100){return 'future_edge'}
    if($Now -ge $Session.ExpiresUtcMs){return 'expired_lease'}
    if($Session.Intents.Count -ge 16){return 'intent_capacity'}
    if($Now-$Session.LastIntentUtcMs -lt 300){return 'intent_spacing'}
    return $null
}
function Get-MineComeHudWorldCurrentDecline($State,$Session,$Click) {
    Assert-MineComeProbeContext $State.Context
    if(-not (Test-MineComeHudWorldForeground $State.Context)){return 'host_not_foreground'}
    # The clock follows the potentially slower process/endpoint ownership checks.
    Get-MineComeHudWorldDecline $State $Session $Click ([DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds())
}
function Invoke-MineComeHudWorldClicks($State,$Session) {
    if($State.Failure){throw 'World-click reader is already failed; input will not be retried.'}
    try {
        if($State.Run -cne $Session.Run -or $State.Context.GamePid -ne $Session.Context.GamePid -or $State.Context.GameStartedUtc -ne $Session.Context.GameStartedUtc){throw 'World-click relay owner differs.'}
        foreach($line in @(Read-MineComeHudWorldClickLines $State)){
            $click=ConvertFrom-MineComeHudWorldClick $line $State.Run $State.Sequence
            if($null -eq $click){continue}
            $State.Sequence=$click.sequence
            $record=[pscustomobject]@{sequence=$click.sequence;utc_ms=$click.utc_ms;action=$click.action;observed_utc_ms=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds();status='pending';reason=$null;intent_ordinal=0;request_id=0L}
            $State.Clicks.Add($record)
            $reason=Get-MineComeHudWorldCurrentDecline $State $Session $click
            if($reason){$record.status='declined';$record.reason=$reason;continue}
            # Recheck immediately after Send's relay health/log reads. Waiting for
            # an earlier receipt can age later edges; they are never replayed.
            $receipt=Send-MineComeHudStoneIntent $Session -Action $click.action -BeforeDispatch {Get-MineComeHudWorldCurrentDecline $State $Session $click}
            if(-not $receipt.accepted){$record.status='declined';$record.reason=$receipt.reason;continue}
            $record.status='sent';$record.intent_ordinal=$receipt.ordinal;$record.request_id=$receipt.request_id
        }
    }catch{$State.Failure=$_.Exception.Message;if($State.Clicks.Count -gt 0 -and $State.Clicks[-1].status -ceq 'pending'){$State.Clicks[-1].status='failed';$State.Clicks[-1].reason=$State.Failure};throw}
}
function Assert-MineComeHudWorldClicks($State,$Session) {
    if($State.Failure -or $State.Run -cne $Session.Run -or $State.Sequence -ne $State.Clicks.Count -or $State.Sequence -gt 16){throw 'World-click reader evidence failed.'}
    $sent=@($State.Clicks | Where-Object status -CEQ 'sent')
    if($sent.Count -ne $Session.Intents.Count){throw 'World-click intent count differs.'}
    for($index=0;$index -lt $sent.Count;$index++){
        $click=$sent[$index];$intent=$Session.Intents[$index]
        if(-not $intent.accepted -or $click.intent_ordinal -ne $intent.ordinal -or $click.request_id -ne $intent.request_id -or $click.action -ne $intent.action){throw 'World-click/intent correlation differs.'}
    }
    foreach($click in $State.Clicks){if($click.status -cnotin @('sent','declined')){throw 'World-click admission incomplete.'}}
}
function Get-MineComeHudWorldClickEvidence($State,$Session) {
    [ordered]@{
        schema=1;kind='minecome_hud_world_clicks_v1';run=$State.Run;path=$State.Path;file_identity=$State.Identity
        initial_offset=$State.InitialOffset;final_offset=$State.Offset;bytes_read=$State.ReadBytes;pending_bytes=$State.Pending.Length
        observed_clicks=$State.Clicks.Count;sent_clicks=@($State.Clicks|Where-Object status -CEQ 'sent').Count;declined_clicks=@($State.Clicks|Where-Object status -CEQ 'declined').Count
        clicks=@($State.Clicks.ToArray());failure=$State.Failure;relay_run=$Session.Run
        physical_input_verified=$false;engine_mirroring_verified=$false;visual_verified=$false;os_input_generated=$false
    }
}
